package android.app; import android.content.*; public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2;public Intent intent;PendingIntent(Intent i){intent=i;}public static PendingIntent getBroadcast(Context c,int id,Intent i,int flags){return new PendingIntent(i);}public static PendingIntent getActivity(Context c,int id,Intent i,int flags){return new PendingIntent(i);}}
